export PATH="/opt/conda/bin:$PATH" && source /root/.bashrc && conda activate geoapps_env && cat > /workspace/repo/tests/conftest.py << 'EOF'
import sys
import pytest

# 在导入任何测试模块之前修补 pymatsolver
def pytest_configure(config):
    try:
        import pymatsolver
        if hasattr(pymatsolver, 'SolverLU'):
            pymatsolver.PardisoSolver = pymatsolver.SolverLU
        else:
            # 如果 SolverLU 不存在，尝试其他求解器
            if hasattr(pymatsolver, 'Solver'):
                pymatsolver.PardisoSolver = pymatsolver.Solver
            else:
                # 如果都没有，创建一个虚拟类
                class DummySolver:
                    pass
                pymatsolver.PardisoSolver = DummySolver
        # 确保模块属性已更新
        sys.modules['pymatsolver'].PardisoSolver = pymatsolver.PardisoSolver
        print('Patched pymatsolver.PardisoSolver')
    except ImportError:
        pass
EOF
# 测试修补是否有效
python -c "import sys; sys.path.insert(0, '/workspace/repo/tests'); import conftest; import pymatsolver; print('PardisoSolver present:', hasattr(pymatsolver, 'PardisoSolver'))" 2>&1

